insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p163', 'allemand', '3AS', 17, 163, 'L8 3AS p163 — Synonyme + Gegenteile (Traumberufe) + 4 Antworten', E'5. Ersetzen Sie die unterstrichenen Wörter durch das passende Synonym aus dem Text.\n- Filmstars verdienen viel Geld. Außerdem sind sie sehr berühmt.\n- Die Arbeit des Piloten ist schwer.\n- Während einer langen Reise können die Passagiere miteinander reden.\n- Die Arbeit eines Arztes fordert viel Zeit.\n6. Wie heißt das Gegenteil von den unterstrichenen Wörtern ?\n- Die Krimifilme sind …………, dagegen sind die politischen Programme langweilig.\n- Der Pilot arbeitet ………… nachts, dagegen arbeiten die Beamten selten nachts.\n- Die Arbeit der Krankenschwester ist …………, dagegen ist die Arbeit der Lehrer leichter.\n7. Antworten Sie.\n1. Was ist Mathias Traumberuf ? Warum ?\n2. Warum will Markus als Fussballprofi spielen ?\n3. Warum möchte Anne in einem Krankenhaus arbeiten?\n4. Warum will Inge Filmstar werden ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p164', 'allemand', '3AS', 17, 164, 'L8 3AS p164 — Welche Berufe ? Sätze mit Notizen (Landwirt-Beispiel) + 8 Fotos', E'Welche Berufe üben diese Personen aus ? Wie finden Sie diese Berufe? Schreiben Sie Sätze mit Hilfe der Notizen aus dem Kasten.\n8 Fotos : Tontechniker/DJ · Geiger · Soldat · Arzt am Schreibtisch · Schweißer · Computerarbeiterin · Ärztin mit Stethoskop · Piloten im Cockpit\nKasten : viel / wenig Geld verdienen · viel Arbeit haben · einen sehr schönen Beruf haben · den ganzen Tag arbeiten · eine saubere Arbeit haben · eine schmutzige Arbeit haben · wenig Arbeit haben · eine spannende Arbeit machen · schwer arbeiten müssen · nachts arbeiten müssen · eine leichte Arbeit tun · eine schwere Arbeit machen · eine gefährliche Arbeit schaffen · keine Freizeit haben · schlechte Arbeitszeiten haben · eine interessante Arbeit machen\nBeispiel : Ein Landwirt macht eine schwere Arbeit, weil er meistens den ganzen Tag arbeiten muss. Er verdient vielleicht wenig Geld und hat keine Freizeit.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p165', 'allemand', '3AS', 17, 165, 'L8 3AS p165 — Wiederholung Zum Sprechen : Statistik «Im Ausland arbeiten» (männl/weibl/Gesamt)', E'Wiederholung — Zum Sprechen\n1. Welche Informationen gibt Ihnen diese deutsche Statistik ?\n? Möchten Sie später im Ausland arbeiten\n(männl. n = 970 · weibl. n = 1702 · Gesamt n = 2672)\nnein : 8 / 14 / 12\nweiß nicht : 10 / 14 / 12\nja, ich spiele mit dem Gedanken : 65 / 61 / 62\nja, ich habe konkrete Pläne : 15 / 10 / 12\nja, ich arbeite schon im Ausland : 3 / 1 / 2\n2. Diskutieren Sie über diese Statistik.\n3. Wie könnte die Statistik in Algerien aussehen ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p166', 'allemand', '3AS', 17, 166, 'L8 3AS p166 — Zum Lesen : Stellenangebot DOLMETSCHERIN (AFSUR)', E'Zum Lesen\n1. Lesen Sie die folgenden Stellangebote.\nSTELLENANGEBOTE — DOLMETSCHERIN\nBerufliche und persönliche Voraussetzungen :\n- sehr gute Englisch und Deutsch Kenntnisse.\n- Osteuropäische Sprachen von Vorteil, vorzugsweise Ungarisch und Tschechisch.\n- schnelle Auffassungsgabe, kommunikativ.\nAufgabenbereich / Stellenbeschreibung :\n- Übersetzung auf Stundenbasis.\n- Betreuung auch am Wochenende.\nDas Angebot :\n- interessantes und eigenverantwortliches Aufgabengebiet.\n- Reisemöglichkeiten in ferne Länder.\nFalls Sie in einem starken, zukunftsorientierten Team mitarbeiten möchten, freuen wir uns auf ihre aussagekräftige Bewerbung. Ihre Unterlagen richten Sie bitte per E-Mail oder Post an :\nAFSUR – Direct Mobile Communications GmbH. Campus 21, Goethe – Straße / 2345 Brunn am Gebirge. E-Mail : karrier@ afsur.de', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p167', 'allemand', '3AS', 17, 167, 'L8 3AS p167 — Stellenangebot VERKAUFSINNENDIENST MITARBEITERIN (DEMS) + Ihre Meinung', E'STELLENANGEBOTE — VERKAUFSINNENDIENST MITARBEITERIN\nAufgabenbereich / Stellenbeschreibung :\n- Kundenbetreuung\n- Terminisierung und Vorbereitung von Meetings\n- Organisation\n- interne und externe Korrespondenz\n- Pflege und Wartung der Firmen – und Geschäftsunterlagen, bzw. Adressen\nBerufliche und persönliche Voraussetzungen :\n- kaufmännische Ausbildung und Berufserfahrung mindestens 4 Jahre\n- perfekte MS-Office Kenntnisse (Word, Excel, PowerPoint)\n- stressresistent\n- selbständiges und vorausschauendes Arbeiten\n- Engagement und Flexibilität\nDas Angebot :\n- Gute Entwicklungs- und Fortbildungsmöglichkeiten\n- Interessantes Gehalt\nFalls Sie in einem starken, zukunftsorientierten Team arbeiten möchten, senden Sie Ihre Bewerbungsunterlagen (vorzugsweise per E-Mail) an :\nDEMS – Direct Mobile Communications GmbH, Campus 21, Goethe Straße / 2345 Brunn am Gebirge, E-Mail : karriere@afsur.de\n2. Welches Stellangebot interessiert Sie ? Warum ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
